import React, { Component } from "react";
import "./Login.css";

export default class Login extends Component {
  constructor(props) {
    super(props);
    this.state = {
      activeTab: "Sign up",
      formData: {},
      buttonsdata: [],
      left: [],
      right: [],
      loginFormData: {},
      loginButtonsdata: [],
      loginText: [],
      loginImages: {},
      signupImages: {},
      pageDataSignup: null,
      pageDataLogin: null
    };
  }

  componentDidMount() {
    this.fetchPageData("Signup");
    this.fetchPageData("Login");
    // this.fetchSignupage();
  }

  // fetchSignupage = () => {
  //   fetch(`http://localhost:3001/form_content/3`, {
  //     method: "POST",
  //     headers: {
  //       'Content-Type': 'application/json'
  //     },
  //     body: JSON.stringify({}),
  //   })
  //     .then((response) => response.json())
  //     .then((data) => {
  //       if (data && Array.isArray(data)) {
  //         if (data[0].FormName === 'Signup') {
  //           this.setState({
  //             formData: this.buildInitialFormData(data),
  //             buttonsdata: data.buttons,
  //             left: data.filter(field => field.side === 'left'),
  //             right: data.filter(field => field.side === 'right'),
  //             signupImages: { img1: data.Img1, img2: data.Img2 },
  //           });
  //         } else if (data[0].FormName === "Login") {
  //           this.setState({
  //             loginFormData: this.buildInitialFormData(data),
  //             loginButtonsdata: data.buttons,
  //             loginText: data,
  //             loginImages: { img1: data.Img1, img2: data.Img2 },
  //           });
  //         } else {
  //           console.error("Unexpected data", data);
  //         }
  //       }
  //     })
  //     .catch((error) => console.error("Error fetching signup data:", error));
  // }

  fetchPageData = (pageType) => {
    debugger
    const pageId = pageType === "Signup" ? 3 : 4;
    fetch(`http://localhost:3001/pages/${pageId}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({})
    })
      .then(response => response.json())
      .then(page => {
        if (pageType === "Signup") {
          this.setState({ pageDataSignup: page });
        } else {
          this.setState({ pageDataLogin: page });
        }
      })
      .catch(error => console.error('Error fetching data:', error));
  }

  buildInitialFormData = (data) => {
    const initialFormData = {};
    data?.forEach((field) => {
      if (field.placeholder) {
        initialFormData[field.placeholder.replace(/ /g, "").toLowerCase()] = field.value;
      } else if (field.left || field.right) {
        field.left?.forEach((subField) => {
          initialFormData[
            subField.placeholder.replace(/ /g, "").toLowerCase()
          ] = subField.value;
        });
        field.right?.forEach((subField) => {
          initialFormData[
            subField.placeholder.replace(/ /g, "").toLowerCase()
          ] = subField.value;
        });
      }
    });
    return initialFormData;
  };

  setActiveTab = (tab) => {
    this.setState({ activeTab: tab });
  };

  handleChange = (e) => {
    const { name, value } = e.target;
    this.setState((prevState) => ({
      formData: {
        ...prevState.formData,
        [name]: value,
      },
    }));
  };

  render() {
    const {
      activeTab,
      formData,
      buttonsdata,
      left,
      right,
      loginFormData,
      loginButtonsdata,
      loginText,
      loginImages,
      signupImages,
    } = this.state;

    return (
      <div className="content-container">
        <div className="formboxx">
          <div className="button-boxx">
            {buttonsdata?.map((value, index) => (
              <button
                key={index}
                type="button"
                className={`toggle-btn1 ${
                  activeTab === value.text ? "active" : ""
                }`}
                onClick={() => this.setActiveTab(value.text)}
              >
                {value.text}
              </button>
            ))}
          </div>

          <div className="social-icons">
            <img
              src={
                activeTab === "Sign up" ? signupImages.img1 : loginImages.img1
              }
              alt="social icon 1"
            />
            <img
              src={
                activeTab === "Sign up" ? signupImages.img2 : loginImages.img2
              }
              alt="social icon 2"
            />
          </div>

          {activeTab === "Sign up" && (
            <form className="input-group">
              <div className="input-left">
                {left?.map((item, index) => (
                  <input
                    key={index}
                    type={item.type}
                    className="input-field"
                    placeholder={item.placeholder}
                    name={item.placeholder.replace(/ /g, "").toLowerCase()}
                    value={
                      formData[
                        item.placeholder.replace(/ /g, "").toLowerCase()
                      ] || ""
                    }
                    onChange={this.handleChange}
                    required
                  />
                ))}
              </div>
              <div className="input-right">
                {right?.map((item, index) => (
                  <input
                    key={index}
                    type={item.type}
                    className="input-field"
                    placeholder={item.placeholder}
                    name={item.placeholder.replace(/ /g, "").toLowerCase()}
                    value={
                      formData[
                        item.placeholder.replace(/ /g, "").toLowerCase()
                      ] || ""
                    }
                    onChange={this.handleChange}
                    required
                  />
                ))}
              </div>
              <button type="submit" className="submit-btnn">
                Sign up
              </button>
            </form>
          )}

          {activeTab === "Log in" && (
            <form className="input-group_login">
              {loginText.map((item, index) => (
                <input
                  key={index}
                  type={item.type}
                  className="input-field1_login"
                  placeholder={item.placeholder}
                  name={item.placeholder.replace(/ /g, "").toLowerCase()}
                  value={
                    loginFormData[
                      item.placeholder.replace(/ /g, "").toLowerCase()
                    ] || ""
                  }
                  onChange={this.handleChange}
                  required
                />
              ))}
              <a href="#" className="forget">
                Forget/Change your password?
              </a>
              <button type="submit" className="submit-btnn">
                Log in
              </button>
            </form>
          )}
        </div>
      </div>
    );
  }
}
